<script setup lang="ts">
import {ref,watch} from 'vue';import axios from 'axios';import {RouterLink} from 'vue-router';
import MessageBubble,{type Message} from './MessageBubble.vue';import ReplyComposer from './ReplyComposer.vue';
const props=defineProps<{placeId:number;rootId?:number}>();const emit=defineEmits<{changed:[]}>();
interface Thread{message:Message;replies:Message[]}
const me=ref('');
const threads=ref<Thread[]>([]),target=ref<Message|null>(null),error=ref(''),loading=ref(false),more=ref(false);let sequence=0;
async function load(append=false){const s=++sequence;loading.value=true;error.value='';try{if(!me.value)me.value=(await axios.get('/api/auth/me')).data.username;if(props.rootId){const after=append?threads.value[0]?.replies.at(-1)?.id||0:0;const {data}=await axios.get('/api/conversations/'+props.rootId,{params:{after}});if(s!==sequence)return;if(append&&threads.value[0])threads.value[0].replies.push(...data.replies);else threads.value=[data];more.value=data.replies.length===50;}else{const before=append?threads.value.at(-1)?.message.id||0:0;const {data}=await axios.get('/api/conversations',{params:{placeId:props.placeId,before}});if(s!==sequence)return;threads.value=append?[...threads.value,...data]:data;more.value=data.length===20;}}catch{error.value='对话加载失败，请重试';}finally{if(s===sequence)loading.value=false;}}
async function remove(id:number){try{const token=(await axios.get('/api/auth/csrf')).data.token;await axios.delete('/api/campus/places/'+props.placeId+'/comments/'+id,{headers:{'X-XSRF-TOKEN':token}});await saved();}catch{error.value='删除失败，请重试';}}
async function saved(){target.value=null;await load();emit('changed');}
watch(()=>[props.placeId,props.rootId],()=>{target.value=null;threads.value=[];load();},{immediate:true});
</script>
<template><div class="thread-board"><ReplyComposer v-if="!rootId" :place-id="placeId" @saved="saved"/><p v-if="loading" role="status">正在加载对话…</p><p v-if="error" role="alert">{{error}} <button @click="load()">重试</button></p><p v-if="!loading&&!threads.length">还没有发言，欢迎提出第一个问题。</p><section v-for="thread in threads" :key="thread.message.id" class="thread"><MessageBubble :message="thread.message" :can-delete="thread.message.username===me" @remove="remove" @reply="target=$event"/><ReplyComposer v-if="target?.id===thread.message.id" :key="target.id" :place-id="placeId" :parent-id="target.id" :reply-name="target.username" @saved="saved" @cancel="target=null"/><div class="reply-region"><div v-for="reply in thread.replies" :key="reply.id"><MessageBubble :message="reply" :can-delete="reply.username===me" @remove="remove" @reply="target=$event"/><ReplyComposer v-if="target?.id===reply.id" :key="target.id" :place-id="placeId" :parent-id="target.id" :reply-name="target.username" @saved="saved" @cancel="target=null"/></div><RouterLink v-if="!rootId&&thread.message.replyCount" :to="'/campus/'+placeId+'/conversations/'+thread.message.id" class="details-link">查看对话详情 · 共 {{thread.message.replyCount}} 条回复 →</RouterLink><p v-if="!rootId&&thread.message.replyCount>2" class="preview-note">当前显示最早的两条回复</p><button v-if="rootId&&!target" class="answer" @click="target=thread.message">回复这条对话</button></div></section><button v-if="more" :disabled="loading" @click="load(true)">{{rootId?'加载后续回复':'加载更多对话'}}</button></div></template>
<style scoped>.thread{border-top:1px solid #e4e3db;padding:10px 0 25px}.reply-region{margin-left:52px;border-left:2px solid #e9e2d3;padding-left:15px}.details-link{display:inline-block;font-size:12px;color:#94744c;margin:10px 0;text-decoration:none}.preview-note{font-size:10px;color:#8a8c80}.answer{background:none;border:0;color:#94744c;padding:10px 0;cursor:pointer}@media(max-width:500px){.reply-region{margin-left:20px;padding-left:9px}}</style>
